"""T-032: the datapack part of the Spider Thicket, written by tools/build/r1_spiders.py: function/spiders/gen/*, dialog/spiders/*,
function/heather/hook/hunter_saved (the quest's hook of T-031: q 0 or 1 -> 2), zones/nofire.txt (the fire ban of the place for the
staffs: tools/gen_seer.py). Generated, do not edit. The hand-written logic: function/spiders/*.mcfunction.

Scores (objective le.sp, fake players): #near players near the place (the loop works only then), #t the loop counter, #sec seconds,
#df the difficulty (0 peaceful), #dt the day time, #day the day, #gt the game time; the elite spiders, per point N (1..9): #gN the
generation, #sN 1 = spawned (alive or unloaded), #dN 1 = killed (back at the next dawn while the Mistress lives: #day > #kN), #mN
seconds missing at a loaded point; the trip wires: #tcK loops (5 t) of the cool-down of wire K; the Mistress: #boss 0 alive / 1 dead
(copy of storage last_ember:spiders boss), #bs 0 asleep / 1 awake, #bgen her generation, #bmiss seconds missing, #fight the fight's
number, #innest live players in the nest, #empty seconds with none, #web seconds to the next web, #brood 1 = released this fight,
#bhalf = half of her max health; the cocoon: #cuts, #cutt the game time of the last cut, #cb 1 = the brood came at the first cut;
Toivo: #toivo 0 in the cocoon / 1 free in the thicket / 2 at home (copy of storage last_ember:spiders toivo), #talked 1 = somebody
talked to him (he may go home), #tgen his generation, #tmiss seconds missing; #rang the strokes of the far bell (tests).
Entities: the elites (spider le.sp_el + le.sp_N, le.spn = N, le.spg = #gN; le.sprest resting (NoAI), le.spawk awake), the Mistress
(spider le.sp_boss, le.giant, le.keep, le.noelite; le.spbg = #bgen), the brood (cave_spider le.sp_brood), Toivo (mannequin le.toivo +
interaction le.sp_talk + seat le.sptseat, all le.spt with le.sptg = #tgen), the cocoon's interaction le.sp_coc, the bow (item_display
le.spbow), the things of the victims (item_display le.spitem), the stands (armor_stand le.spstand), the web markers (marker le.spweb).
Players: le.sptrig (trigger: 1 «Что ты видел?», 2 «Иди домой»), le.spwin the last window (1 Toivo first, 2 seen, 3 later, 4 belfry,
5 the ringer: Toivo is home, 6 the ringer: about the grandson), tags le.sptk (talked to Toivo), le.sprew (the ringer's reward taken),
le.sppart + le.spfight (hit the Mistress in fight #fight)."""
import json, math, os

def tx(t, color="white", italic=False): return {"text": t, "color": color, "italic": italic}
NAME_T = "Тойво"
SKIN_T = "last_ember:entity/toivo"
BOW = '{id:"minecraft:stick",count:1,components:{"minecraft:item_model":"last_ember:spiders/toivo_bow"}}'
DLG = {   # HQ T-032, 4: word for word
    "toivo_first": "Живой… Я живой? Она держит нас про запас, как дичь в погребе. Деда видели? Скажите ему, что я дойду. Сам. Ноги только вспомнят.",
    "toivo_seen": "Про кости у дороги я деду не зря писал. От тракта на кладбище, недалеко за Приютом, в холмы уходят кости. Цепочкой, как нарочно. Ведут на восток, к старому дубу. Под дубом лежит упавший ствол, а под стволом ступени вниз. Оттуда пахнет, как из котла. Там живёт кто-то, кто ест не дичь. Я туда не полез. Вы, может, полезете. Только не по одному.",
    "toivo_later": "Отдышусь и пойду. Лук нашёл, значит, и дорогу найду.",
    "toivo_belfry": "Дед ворчит, что я его чуть не схоронил. А я ему про дуб рассказал, он велел вам не ходить. Я бы пошёл. Вдвоём, не меньше.",
    "ringer_home": "Тойво дошёл. Сидит внизу и ест за троих. Не знаю, чем вам платить. Возьмите вот это. И ещё: колокол теперь звонит и за вас. Где бы вы ни легли, я услышу и позвоню.",
    "ringer_grandson": "Тойво дома. Ворчит, что тетива отсырела. Спасибо вам.",
}
ITEM = {   # the things of the victims (item_display on the ground, not to be taken)
    "leather_helmet": '{id:"minecraft:leather_helmet",count:1}', "shield": '{id:"minecraft:shield",count:1}', "torch": '{id:"minecraft:torch",count:1}',
    "leather_boots": '{id:"minecraft:leather_boots",count:1}', "bone": '{id:"minecraft:bone",count:1}',
    "rag": '{id:"minecraft:white_carpet",count:1}', "arrow": '{id:"minecraft:arrow",count:1}', "bowl": '{id:"minecraft:bowl",count:1}'}
BELFRY = (36.5, 130.0, -502.5, 90.0)      # Toivo at home: on the bell platform of Heather's church, east of the ringer (T-031: ringer 33.5 130 -504.5)

def box(b): return "x=%d,y=%d,z=%d,dx=%d,dy=%d,dz=%d" % (b[0], b[1], b[2], b[3] - b[0], b[4] - b[1], b[5] - b[2])

def run(meta):
    import r1_spiders as R
    import spiders_plan as P
    ROOT, DP = R.ROOT, R.DP
    GEN = os.path.join(DP, "function/spiders/gen"); os.makedirs(GEN, exist_ok=True)
    for f in os.listdir(GEN):
        if f.endswith(".mcfunction"): os.remove(os.path.join(GEN, f))
    hdr = "# generated by tools/build/r1_spiders.py (spiders_dp.py): "
    def w(name, lines): open(os.path.join(GEN, name + ".mcfunction"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
    gr = P.grids()
    px1, pz1, px2, pz2 = P.PLACE
    zlo = meta["floor"] - 4; zhi = meta["zone_nest"][4] + 20
    PBOX = (px1, zlo, pz1, px2, zhi, pz2)
    NEAR = (px1 - 48, zlo - 40, pz1 - 48, px2 + 48, zhi + 40, pz2 + 48)
    x1, z1, x2, z2 = meta["nest_r"]; F = meta["floor"]
    lid = {(x, z): P.B4(gr, x, z) for x in range(x1, x2 + 1) for z in range(z1, z2 + 1)}
    lidmax = max(lid.values())
    LEASH = (x1 - 1, F - 1, z1 - 1, x2 + 1, lidmax + 1, z2 + 1)
    meta["leash"] = list(LEASH); meta["pbox"] = list(PBOX)
    # the nest's cavity: boxes of 4 x 4 columns up to the lowest lid over them (a player on the lid is not in the nest)
    subs = []
    for bx in range(x1, x2 + 1, 4):
        for bz in range(z1, z2 + 1, 4):
            ex, ez = min(bx + 3, x2), min(bz + 3, z2)
            top = min(lid[(x, z)] for x in range(bx, ex + 1) for z in range(bz, ez + 1)) - 1
            subs.append((bx, F, bz, ex, top, ez))
    meta["nest_cells"] = [list(s) for s in subs]
    # ---- the elite spiders: one function per point (the arguments of a macro would be re-parsed for > 8 points, CLAUDE.md: Нагрузка)
    E = meta["points"]["elites"]
    for n, (x, y, z, yaw) in enumerate(E, 1):
        w("spawn_%d" % n, [hdr + "the elite spider %d on her point: resting (NoAI), elite by T-014 (out of its limits: le.sp_el)" % n,
                           "scoreboard players add #g%d le.sp 1" % n,
                           "execute as @e[type=minecraft:spider,tag=le.sp_%d] run function last_ember:spiders/vanish" % n,
                           'summon minecraft:spider %.2f %.2f %.2f {Tags:["le.sp_el","le.sp_%d","le.sprest","le.keep","le.noelite","le.eq_done","le.spnew"],NoAI:1b,PersistenceRequired:1b,Rotation:[%.1ff,0f]}' % (x, y, z, n, yaw),
                           "execute as @e[type=minecraft:spider,tag=le.spnew] at @s run function last_ember:elite/make",
                           "scoreboard players set @e[type=minecraft:spider,tag=le.spnew] le.spn %d" % n,
                           "scoreboard players operation @e[type=minecraft:spider,tag=le.spnew] le.spg = #g%d le.sp" % n,
                           "tag @e[type=minecraft:spider,tag=le.spnew] remove le.spnew",
                           "scoreboard players set #s%d le.sp 1" % n, "scoreboard players set #d%d le.sp 0" % n, "scoreboard players set #m%d le.sp 0" % n])
        w("pt_%d" % n, [hdr + "every second: point %d - alive, missing (3 s at a loaded point: killed), killed (back at the next dawn while the Mistress lives, nobody within 48)" % n,
                        "execute unless loaded %d %d %d run return 0" % (math.floor(x), int(y), math.floor(z)),
                        "execute store result score #c le.sp if entity @e[type=minecraft:spider,tag=le.sp_%d]" % n,
                        "execute if score #c le.sp matches 1.. run return run scoreboard players set #m%d le.sp 0" % n,
                        "execute if score #df le.sp matches 0 run return 0",
                        "execute if score #s%d le.sp matches 0 if score #d%d le.sp matches 0 run return run function last_ember:spiders/gen/spawn_%d" % (n, n, n),
                        "execute if score #s%d le.sp matches 1 run scoreboard players add #m%d le.sp 1" % (n, n),
                        "execute if score #s%d le.sp matches 1 if score #m%d le.sp matches 3.. run scoreboard players operation #k%d le.sp = #day le.sp" % (n, n, n),
                        "execute if score #s%d le.sp matches 1 if score #m%d le.sp matches 3.. run scoreboard players set #d%d le.sp 1" % (n, n, n),
                        "execute if score #s%d le.sp matches 1 if score #m%d le.sp matches 3.. run scoreboard players set #s%d le.sp 0" % (n, n, n),
                        "execute if score #d%d le.sp matches 1 if score #boss le.sp matches 0 if score #dt le.sp matches 0..1000 if score #day le.sp > #k%d le.sp unless entity @a[gamemode=!spectator,x=%.1f,y=%.1f,z=%.1f,distance=..48] run function last_ember:spiders/gen/spawn_%d" % (n, n, x, y, z, n)])
        w("home_%d" % n, [hdr + "the elite spider %d back on her point" % n, "tp @s %.2f %.2f %.2f %.1f 0" % (x, y, z, yaw)])
    I = [hdr + "the scores of the points (load: only those not set yet)"]
    for n in range(1, len(E) + 1):
        for k in ("g", "s", "d", "m", "k"): I.append("execute unless score #%s%d le.sp = #%s%d le.sp run scoreboard players set #%s%d le.sp 0" % (k, n, k, n, k, n))
    for k in ("tc1", "tc2", "tc3", "bgen", "bmiss", "bs", "fight", "empty", "web", "brood", "cuts", "cutt", "cb", "talked", "tgen", "tmiss", "rang", "paid"):
        I.append("execute unless score #%s le.sp = #%s le.sp run scoreboard players set #%s le.sp 0" % (k, k, k))
    w("init", I)
    w("points", [hdr + "every second (players near): the points of the elite spiders"] + ["function last_ember:spiders/gen/pt_%d" % n for n in range(1, len(E) + 1)])
    w("home", [hdr + "as an elite spider: to her point (by le.spn)"] + ["execute if score @s le.spn matches %d run function last_ember:spiders/gen/home_%d" % (n, n) for n in range(1, len(E) + 1)])
    w("dawn_all", [hdr + "admin (spiders/reset): every point spawns now"] + ["function last_ember:spiders/gen/spawn_%d" % n for n in range(1, len(E) + 1)])
    w("forget", [hdr + "peaceful: the elite spiders vanish (monsters) and are not killed: on easy+ they are on their points at once"] +
      ["scoreboard players set #s%d le.sp 0" % n for n in range(1, len(E) + 1)] + ["scoreboard players set #d%d le.sp 0" % n for n in range(1, len(E) + 1)])
    w("genchk", [hdr + "as an elite spider: one of an old generation (a double from a chunk loaded late) goes"] +
      ["execute if score @s le.spn matches %d unless score @s le.spg = #g%d le.sp run return run function last_ember:spiders/vanish" % (n, n) for n in range(1, len(E) + 1)])
    # ---- the near test, the nest
    w("near", [hdr + "#near = players near the place (box + 48)", "execute store result score #near le.sp if entity @a[%s]" % box(NEAR)])
    w("in_nest", [hdr + "as a player: #in 1 when inside the nest's cavity (under the lid; 4 x 4 column boxes up to the lowest lid over them)",
                  "scoreboard players set #in le.sp 0"] + ["execute if entity @s[%s] run return run scoreboard players set #in le.sp 1" % box(s) for s in subs])
    w("count_nest", [hdr + "#innest = live players (not spectator/creative) inside the nest's cavity (@e selects only the living: @a would count a dead one)", "scoreboard players set #innest le.sp 0",
                     "execute as @e[type=minecraft:player,gamemode=!spectator,gamemode=!creative,%s] run function last_ember:spiders/count_one" % box(LEASH)])
    bx, by, bz = meta["points"]["boss"]
    w("boss_put", [hdr + "the Mistress asleep on her lair (a new generation: the old one goes wherever she is)",
                   "scoreboard players add #bgen le.sp 1",
                   "execute as @e[type=minecraft:spider,tag=le.sp_boss] run function last_ember:spiders/vanish",
                   'summon minecraft:spider %.2f %.2f %.2f {Tags:["le.sp_boss","le.giant","le.keep","le.noelite","le.eq_done","le.rolled","le.spbnew"],NoAI:1b,PersistenceRequired:1b,CustomName:{text:"Хозяйка Чащи",color:"dark_red"},CustomNameVisible:1b,Rotation:[90f,0f],attributes:[{id:"minecraft:scale",base:3.0d},{id:"minecraft:max_health",base:120.0d},{id:"minecraft:follow_range",base:32.0d}],Health:120.0f}' % (bx, by, bz),
                   "scoreboard players operation @e[type=minecraft:spider,tag=le.spbnew] le.spbg = #bgen le.sp", "tag @e[type=minecraft:spider,tag=le.spbnew] remove le.spbnew",
                   "scoreboard players set #bs le.sp 0", "scoreboard players set #bmiss le.sp 0", "scoreboard players set #brood le.sp 0"])
    w("boss_home", [hdr + "as the Mistress: back on her lair", "tp @s %.2f %.2f %.2f" % (bx, by, bz)])
    w("boss_check", [hdr + "every second (the lair loaded): the Mistress of this generation there (asleep and missing 2 s: again; awake and missing: dead)",
                     "execute unless loaded %d %d %d run return 0" % (math.floor(bx), int(by), math.floor(bz)),
                     "execute if entity @e[type=minecraft:spider,tag=le.sp_boss] run return run scoreboard players set #bmiss le.sp 0",
                     "scoreboard players add #bmiss le.sp 1",
                     "execute if score #bs le.sp matches 1 if score #bmiss le.sp matches 2.. run return run function last_ember:spiders/boss_dead",
                     "execute if score #bmiss le.sp matches 2.. run function last_ember:spiders/gen/boss_put"])
    for k in range(1, 5):
        hp = 120 + 40 * k
        w("boss_hp_%d" % k, [hdr + "as the Mistress waking with %d player(s) in the nest: health %d" % (k, hp),
                             "attribute @s minecraft:max_health base set %d" % hp, "data modify entity @s Health set value %d.0f" % hp, "scoreboard players set #bhalf le.sp %d" % (hp // 2)])
    w("leash", [hdr + "every 5 ticks while awake: the Mistress climbed out of the nest's box -> back on her lair",
                "execute as @e[type=minecraft:spider,tag=le.sp_boss] unless entity @s[%s] run function last_ember:spiders/gen/boss_home" % box(LEASH)])
    walls = [((x1 + x2) / 2 + 0.5, F + 1, z1 + 1.5), (x2 + 0.5 - 1, F + 1, (z1 + z2) / 2 + 0.5), ((x1 + x2) / 2 + 3.5, F + 1, z2 + 0.5 - 2)]
    w("brood_put", [hdr + "the brood at half her health: 3 cave spiders out of the walls"] +
      ['summon minecraft:cave_spider %.1f %d %.1f {Tags:["le.sp_brood","le.keep","le.noelite","le.eq_done","le.rolled"],PersistenceRequired:1b}' % p for p in walls] +
      ["execute positioned %.1f %d %.1f run particle minecraft:block{block_state:\"minecraft:rooted_dirt\"} ~ ~0.5 ~ 0.4 0.6 0.4 0 30" % p for p in walls])
    lp = meta["lair_path"]; q = lp[-6]
    cpos = (q[0] + 0.5, q[2] / 2 + 1, q[1] + 0.5)
    w("brood_cocoon", [hdr + "the first cut of the cocoon while the Mistress lives: her brood (3 cave spiders) crawl up the burrow toward the cocoon; a screech from the pit"] +
      ['summon minecraft:cave_spider %.1f %.1f %.1f {Tags:["le.sp_brood","le.keep","le.noelite","le.eq_done","le.rolled"],PersistenceRequired:1b}' % cpos for _ in range(3)] +
      ["playsound minecraft:entity.spider.death hostile @a[x=%.1f,y=%.1f,z=%.1f,distance=..48] %.1f %.1f %.1f 2 0.5" % (bx, by, bz, bx, by + 6, bz),
       "playsound minecraft:entity.spider.ambient hostile @a[x=%.1f,y=%.1f,z=%.1f,distance=..48] %.1f %.1f %.1f 2 0.6" % (bx, by, bz, bx, by + 6, bz)])
    w("pit_sound", [hdr + "a hiss and a grating from the pit (all within 48)",
                    "playsound minecraft:entity.spider.ambient hostile @a[x=%.1f,y=%.1f,z=%.1f,distance=..48] %.1f %.1f %.1f 2.5 0.55" % (bx, by + 8, bz, bx, by + 6, bz),
                    "playsound minecraft:block.grindstone.use hostile @a[x=%.1f,y=%.1f,z=%.1f,distance=..48] %.1f %.1f %.1f 1.5 0.5" % (bx, by + 8, bz, bx, by + 6, bz)])
    # ---- the trip wires
    T = meta["trips"]; meta["trip_pts"] = []
    for k, t in enumerate(T, 1):
        (h1, h2), wires = t["hooks"], t["wire"]
        mx = sum(c[0] for c in wires) / len(wires) + 0.5; my = wires[0][1]; mz = sum(c[2] for c in wires) / len(wires) + 0.5
        meta["trip_pts"].append([mx, my, mz])
        w("trip_%d" % k, [hdr + "wire %d sprang: every resting elite spider within 32 wakes, the pit hisses (all within 48), 30 s of cool-down" % k,
                          "execute positioned %.1f %d %.1f as @e[type=minecraft:spider,tag=le.sprest,distance=..32] run function last_ember:spiders/wake" % (mx, my, mz),
                          "function last_ember:spiders/gen/pit_sound",
                          "playsound minecraft:block.tripwire.click_on block @a[x=%.1f,y=%d,z=%.1f,distance=..16] %.1f %d %.1f 1 0.6" % (mx, my, mz, mx, my, mz),
                          "scoreboard players set #tc%d le.sp 120" % k, "scoreboard players add #tripped le.sp 1"])
        fix = [hdr + "wire %d: cut or broken - set again when nobody is within 48" % k,
               "setblock %d %d %d minecraft:tripwire_hook[attached=true,facing=%s,powered=false]" % (h1[0], h1[1], h1[2], t["f1"]),
               "setblock %d %d %d minecraft:tripwire_hook[attached=true,facing=%s,powered=false]" % (h2[0], h2[1], h2[2], t["f2"])]
        fix += ["setblock %d %d %d minecraft:tripwire[attached=true,disarmed=false,%s,powered=false]" % (c[0], c[1], c[2], t["ax"]) for c in wires]
        w("trip_fix_%d" % k, fix)
    chk = [hdr + "every 5 ticks (players near): a wire sprang (a hook powered) and not cooling down"]
    for k, t in enumerate(T, 1):
        (h1, h2) = t["hooks"]
        chk.append("execute if score #tc%d le.sp matches 1.. run scoreboard players remove #tc%d le.sp 1" % (k, k))
        for h in (h1, h2):
            chk.append("execute if score #tc%d le.sp matches ..0 if loaded %d %d %d if block %d %d %d minecraft:tripwire_hook[powered=true] run function last_ember:spiders/gen/trip_%d" % (k, h[0], h[1], h[2], h[0], h[1], h[2], k))
    w("trip_chk", chk)
    fx = [hdr + "every second: a wire cut (shears), broken or its hook gone - again when nobody is within 48"]
    for k, t in enumerate(T, 1):
        (h1, h2), wires = t["hooks"], t["wire"]; mx, my, mz = meta["trip_pts"][k - 1]
        cond = "execute if loaded %d %d %d unless entity @a[x=%.1f,y=%d,z=%.1f,distance=..48]" % (h1[0], h1[1], h1[2], mx, my, mz)
        for c in wires: fx.append("%s unless block %d %d %d minecraft:tripwire[disarmed=false] run return run function last_ember:spiders/gen/trip_fix_%d" % (cond, c[0], c[1], c[2], k))
        for h in (h1, h2): fx.append("%s unless block %d %d %d minecraft:tripwire_hook run return run function last_ember:spiders/gen/trip_fix_%d" % (cond, h[0], h[1], h[2], k))
    w("trip_fixes", fx)
    # ---- the live cocoon, the bow, Toivo
    lv = meta["live"]; o = lv["origin"]; cx_, cy_, cz_ = o[0] + 1.0, o[1], o[2] + 1.0
    w("cocoon_closed", [hdr + "the live cocoon closed (Toivo inside)", "place template last_ember:spiders/cocoon_live_closed %d %d %d" % tuple(o)])
    w("cocoon_open", [hdr + "the live cocoon cut open", "place template last_ember:spiders/cocoon_live_open %d %d %d" % tuple(o)])
    w("coc_put", [hdr + "the cocoon's interaction (right click with a blade or shears: a cut)", "kill @e[type=minecraft:interaction,tag=le.sp_coc]",
                  'summon minecraft:interaction %.2f %.2f %.2f {Tags:["le.sp_coc"],width:2.4f,height:4.2f,response:1b}' % (cx_, cy_ - 0.1, cz_)])
    bw = lv["bow"]
    w("bow_put", [hdr + "Toivo's bow in the clearing (lying flat)", "kill @e[type=minecraft:item_display,tag=le.spbow]",
                  'summon minecraft:item_display %.2f %.2f %.2f {Tags:["le.spbow"],item:%s,transformation:{left_rotation:[0.7071f,0f,0f,0.7071f],right_rotation:[0f,0f,0f,1f],translation:[0f,0f,0f],scale:[0.9f,0.9f,0.9f]},Rotation:[35f,0f]}' % (bw[0] + 0.7, bw[1], bw[2] - 0.3, BOW)])
    tv = lv["toivo"]
    MAN = ('{Tags:["le.npc","le.keep","le.noelite","le.toivo","le.spt","le.sptnew"],profile:{texture:"%s"},CustomName:{text:"%s",color:"gold"},'
           'CustomNameVisible:1b,hide_description:1b,immovable:1b,Invulnerable:1b,Silent:1b,PersistenceRequired:1b,Rotation:[%.1ff,0f]}')
    yaw_t = 0.0                                     # looks south, out of the clearing (his back to the cocoon)
    meta["toivo_pts"] = dict(thicket=[tv[0], tv[1], tv[2], yaw_t], belfry=list(BELFRY))
    for nm, (x, y, z, yaw), seat in (("thicket", (tv[0], tv[1], tv[2], yaw_t), True), ("belfry", BELFRY, False)):
        L = [hdr + "Toivo %s (a new generation: the old entities go wherever they are, now or when their chunk loads)" % ("sitting by the cocoon" if seat else "at home on the belfry"),
             "scoreboard players add #tgen le.sp 1", "kill @e[tag=le.spt]"]
        if seat:
            # sitting on the ground (as the Advisor in his armchair, T-030: the rider is 0.6 under a marker stand, hips 0.5 over his feet)
            L.append('summon minecraft:armor_stand %.2f %.2f %.2f {Tags:["le.sptseat","le.spt","le.sptnew"],Invisible:1b,Marker:1b,NoGravity:1b,Invulnerable:1b,Rotation:[%.1ff,0f]}' % (x, y + 0.1, z, yaw))
            L.append("summon minecraft:mannequin %.2f %.2f %.2f %s" % (x, y + 0.1, z, MAN % (SKIN_T, NAME_T, yaw)))
            L.append("ride @e[type=minecraft:mannequin,tag=le.sptnew,limit=1] mount @e[type=minecraft:armor_stand,tag=le.sptnew,limit=1]")
            L.append('summon minecraft:interaction %.2f %.2f %.2f {Tags:["le.sp_talk","le.spt","le.sptnew"],width:1.0f,height:1.4f,response:1b}' % (x, y, z))
        else:
            L.append("summon minecraft:mannequin %.2f %.2f %.2f %s" % (x, y, z, MAN % (SKIN_T, NAME_T, yaw)))
            L.append('summon minecraft:interaction %.2f %.2f %.2f {Tags:["le.sp_talk","le.spt","le.sptnew"],width:0.9f,height:2.0f,response:1b}' % (x, y, z))
        L += ["scoreboard players operation @e[tag=le.sptnew] le.sptg = #tgen le.sp", "tag @e[tag=le.sptnew] remove le.sptnew", "scoreboard players set #tmiss le.sp 0"]
        w("toivo_%s" % nm, L)
    tt = meta["toivo_pts"]["thicket"]
    w("toivo_check", [hdr + "every second: Toivo of this generation at his point (missing 2 s at a loaded point: again); at home he comes only when nobody is within 12",
                      "execute if score #toivo le.sp matches 0 run return 0",
                      "execute if score #toivo le.sp matches 1 unless loaded %d %d %d run return 0" % (math.floor(tt[0]), int(tt[1]), math.floor(tt[2])),
                      "execute if score #toivo le.sp matches 2 unless loaded %d %d %d run return 0" % (math.floor(BELFRY[0]), int(BELFRY[1]), math.floor(BELFRY[2])),
                      "execute if score #toivo le.sp matches 1 if entity @e[type=minecraft:mannequin,tag=le.toivo,x=%.2f,y=%.2f,z=%.2f,distance=..2] if entity @e[type=minecraft:interaction,tag=le.sp_talk,x=%.2f,y=%.2f,z=%.2f,distance=..2] run return run scoreboard players set #tmiss le.sp 0" % (tt[0], tt[1], tt[2], tt[0], tt[1], tt[2]),
                      "execute if score #toivo le.sp matches 2 if entity @e[type=minecraft:mannequin,tag=le.toivo,x=%.2f,y=%.2f,z=%.2f,distance=..2] if entity @e[type=minecraft:interaction,tag=le.sp_talk,x=%.2f,y=%.2f,z=%.2f,distance=..2] run return run scoreboard players set #tmiss le.sp 0" % (BELFRY[0], BELFRY[1], BELFRY[2], BELFRY[0], BELFRY[1], BELFRY[2]),
                      "scoreboard players add #tmiss le.sp 1",
                      "execute if score #toivo le.sp matches 1 if score #tmiss le.sp matches 2.. run function last_ember:spiders/gen/toivo_thicket",
                      "execute if score #toivo le.sp matches 2 if score #tmiss le.sp matches 2.. unless entity @a[x=%.2f,y=%.2f,z=%.2f,distance=..12] run function last_ember:spiders/gen/toivo_belfry" % BELFRY[:3]])
    w("toivo_go", [hdr + "Toivo talked to and nobody within 32 of the cocoon: he leaves the thicket (home: storage toivo 2)",
                   "execute unless score #toivo le.sp matches 1 run return 0", "execute unless score #talked le.sp matches 1 run return 0",
                   "execute if entity @a[x=%.2f,y=%.2f,z=%.2f,distance=..32] run return 0" % (cx_, cy_, cz_),
                   "scoreboard players add #tgen le.sp 1", "kill @e[tag=le.spt]",
                   "scoreboard players set #toivo le.sp 2", "data modify storage last_ember:spiders toivo set value 2", "scoreboard players set #tmiss le.sp 2"])
    w("near_toivo", [hdr + "@s within 6 of Toivo: #ok 1", "scoreboard players set #ok le.sp 0",
                     "execute if entity @e[type=minecraft:mannequin,tag=le.toivo,distance=..6] run scoreboard players set #ok le.sp 1"])
    # ---- the props: the stands in the cocoons with remains, the things of the victims, the barrels
    pr = [hdr + "the stands with rags in the cocoons with remains, the things of the victims along the trail (missing or doubled: all again)",
          "kill @e[type=minecraft:armor_stand,tag=le.spstand]", "kill @e[type=minecraft:item_display,tag=le.spitem]"]
    for r in meta["remains"]:
        sx, sy, sz = r["stand"]
        pr.append('summon minecraft:armor_stand %.1f %d %.1f {Tags:["le.spstand"],Invulnerable:1b,NoBasePlate:1b,ShowArms:1b,DisabledSlots:4144959,PersistenceRequired:1b,Rotation:[%.1ff,0f],Pose:{Head:[25f,0f,10f],RightArm:[-20f,0f,10f],LeftArm:[-10f,0f,-15f]},equipment:{head:{id:"minecraft:leather_helmet",count:1},chest:{id:"minecraft:leather_chestplate",count:1},legs:{id:"minecraft:leather_leggings",count:1},mainhand:{id:"minecraft:wooden_sword",count:1}},drop_chances:{head:0.0f,chest:0.0f,legs:0.0f,mainhand:0.0f}}' % (sx + 0.5, sy, sz + 0.5, r["yaw"]))
    for (x, y, z, kd, rot) in meta["points"]["items"]:
        flat = kd not in ("torch", "shield")
        lr = "[0.7071f,0f,0f,0.7071f]" if flat else ("[0f,0f,0.38f,0.92f]" if kd == "torch" else "[0.2588f,0f,0f,0.9659f]")
        pr.append('summon minecraft:item_display %.2f %.2f %.2f {Tags:["le.spitem"],item:%s,transformation:{left_rotation:%s,right_rotation:[0f,0f,0f,1f],translation:[0f,0f,0f],scale:[0.75f,0.75f,0.75f]},Rotation:[%df,0f]}' % (x, y + (0.04 if flat else 0.35), z, ITEM[kd], lr, rot))
    w("props_put", pr)
    p0 = meta["points"]["items"][0]
    w("props_check", [hdr + "every second (the trail loaded): the props are there (3 stands, %d things); Toivo's bow while he is in the cocoon" % len(meta["points"]["items"]),
                      "execute unless loaded %d %d %d run return 0" % (math.floor(p0[0]), int(p0[1]), math.floor(p0[2])),
                      "execute store result score #c le.sp if entity @e[type=minecraft:armor_stand,tag=le.spstand]",
                      "execute store result score #c2 le.sp if entity @e[type=minecraft:item_display,tag=le.spitem]",
                      "execute unless score #c le.sp matches %d run return run function last_ember:spiders/gen/props_put" % len(meta["remains"]),
                      "execute unless score #c2 le.sp matches %d run return run function last_ember:spiders/gen/props_put" % len(meta["points"]["items"]),
                      "execute unless loaded %d %d %d run return 0" % (math.floor(bw[0]), int(bw[1]), math.floor(bw[2])),
                      "execute store result score #c le.sp if entity @e[type=minecraft:item_display,tag=le.spbow]",
                      "execute if score #toivo le.sp matches 0 unless score #c le.sp matches 1 run function last_ember:spiders/gen/bow_put",
                      "execute if score #toivo le.sp matches 1.. if score #c le.sp matches 1.. run kill @e[type=minecraft:item_display,tag=le.spbow]",
                      "execute store result score #c le.sp if entity @e[type=minecraft:interaction,tag=le.sp_coc]",
                      "execute unless score #c le.sp matches 1 run function last_ember:spiders/gen/coc_put"])
    w("barrels", [hdr + "admin (spiders/reset): the barrels in the cocoons with remains again, with their loot (r1/common, T-019)"] +
      ["setblock %d %d %d minecraft:barrel[facing=up,open=false]{LootTable:\"last_ember:chests/r1/common\"} destroy" % tuple(r["barrel"]) for r in meta["remains"]])
    # ---- the fire ban box (the place) for the per-player sweep
    w("fire_near", [hdr + "every second: players inside the place (+ 4) clear the fire round them (spiders/fire, inside the place only)",
                    "execute as @a[%s] at @s run function last_ember:spiders/fire" % box((px1 - 4, zlo - 10, pz1 - 4, px2 + 4, zhi + 30, pz2 + 4))])
    w("fire_clamp", [hdr + "as a player: the box round him clamped to the place (storage last_ember:spiders f.x1..z2)",
                     "execute store result score #fx le.sp run data get entity @s Pos[0]", "execute store result score #fy le.sp run data get entity @s Pos[1]",
                     "execute store result score #fz le.sp run data get entity @s Pos[2]",
                     "scoreboard players operation #x1 le.sp = #fx le.sp", "scoreboard players remove #x1 le.sp 12", "execute if score #x1 le.sp matches ..%d run scoreboard players set #x1 le.sp %d" % (px1 - 1, px1),
                     "scoreboard players operation #x2 le.sp = #fx le.sp", "scoreboard players add #x2 le.sp 12", "execute if score #x2 le.sp matches %d.. run scoreboard players set #x2 le.sp %d" % (px2 + 1, px2),
                     "scoreboard players operation #z1 le.sp = #fz le.sp", "scoreboard players remove #z1 le.sp 12", "execute if score #z1 le.sp matches ..%d run scoreboard players set #z1 le.sp %d" % (pz1 - 1, pz1),
                     "scoreboard players operation #z2 le.sp = #fz le.sp", "scoreboard players add #z2 le.sp 12", "execute if score #z2 le.sp matches %d.. run scoreboard players set #z2 le.sp %d" % (pz2 + 1, pz2),
                     "scoreboard players operation #y1 le.sp = #fy le.sp", "scoreboard players remove #y1 le.sp 6",
                     "scoreboard players operation #y2 le.sp = #fy le.sp", "scoreboard players add #y2 le.sp 6",
                     "execute if score #x1 le.sp > #x2 le.sp run return fail", "execute if score #z1 le.sp > #z2 le.sp run return fail"] +
      ["execute store result storage last_ember:spiders f.%s int 1 run scoreboard players get #%s le.sp" % (k, k) for k in ("x1", "y1", "z1", "x2", "y2", "z2")] + ["return 1"])
    # ---- the tp points for the shots and the tests
    pv, pa = meta["pv"], meta["pa"]
    tps = {"edge": (pa[-1][0] + 0.5, pa[-1][2] / 2 + 1, pa[-1][1] + 0.5), "trail": (pv[len(pv) // 2][0] + 0.5, pv[len(pv) // 2][2] / 2 + 1, pv[len(pv) // 2][1] + 0.5),
           "cocoon": (tt[0], tt[1], tt[2] + 1.0), "nest": (bx, by, bz + 4), "join": (pa[0][0] + 0.5, pa[0][2] / 2 + 1, pa[0][1] + 0.5),
           "hole": (meta["hole"][0] + 1.5, P.B4(gr, meta["hole"][0] + 1, meta["hole"][1] - 2) + 1, meta["hole"][1] - 1.5), "belfry": (BELFRY[0] - 1.0, BELFRY[1], BELFRY[2] - 1.0)}
    for k, (x, y, z) in tps.items(): w("tp_%s" % k, [hdr + "admin: @s to %s" % k, "tp @s %.1f %.1f %.1f" % (x, y, z)])
    meta["tp"] = {k: list(v) for k, v in tps.items()}
    # ---- dialogs (read at the server start only)
    DD = os.path.join(DP, "dialog/spiders"); os.makedirs(DD, exist_ok=True)
    for f in os.listdir(DD): os.remove(os.path.join(DD, f))
    def dump(name, o): json.dump(o, open(os.path.join(DD, name + ".json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    def msg(t): return {"type": "minecraft:plain_message", "contents": tx(t), "width": 300}
    def btn(label, cmd, color="green"): return {"label": tx(label, color), "width": 200, "action": {"type": "minecraft:run_command", "command": cmd}}
    def multi(name, who, text, buttons, exit_label=None):
        o = {"type": "minecraft:multi_action", "title": tx(who, "gold"), "body": [msg(text)], "can_close_with_escape": True, "pause": False,
             "after_action": "close", "columns": 1, "actions": buttons}
        if exit_label: o["exit_action"] = {"label": tx(exit_label, "gray"), "width": 150}
        dump(name, o)
    def notice(name, who, text, label):
        dump(name, {"type": "minecraft:notice", "title": tx(who, "gold"), "body": [msg(text)], "can_close_with_escape": True, "pause": False,
                    "action": {"label": tx(label, "gray"), "width": 150}})
    multi("toivo_first", NAME_T, DLG["toivo_first"], [btn("Что ты видел?", "trigger le.sptrig set 1"), btn("Иди домой", "trigger le.sptrig set 2", "gray")])
    multi("toivo_seen", NAME_T, DLG["toivo_seen"], [btn("Иди домой", "trigger le.sptrig set 2", "gray")])
    multi("toivo_later", NAME_T, DLG["toivo_later"], [btn("Что ты видел?", "trigger le.sptrig set 1"), btn("Иди домой", "trigger le.sptrig set 2", "gray")])
    notice("toivo_belfry", NAME_T, DLG["toivo_belfry"], "Пойдём")
    notice("ringer_home", "Звонарь", DLG["ringer_home"], "Пойдём")
    multi("ringer_grandson", "Звонарь", DLG["ringer_grandson"], [btn("Ещё", "trigger le.htrig set 4")])
    meta["dialogs"] = sorted(os.listdir(DD))
    # ---- the hook of the quest «Внук звонаря» (T-031): q 0 or 1 -> 2 (saved without taking the quest counts too)
    HK = os.path.join(DP, "function/heather/hook"); os.makedirs(HK, exist_ok=True)
    open(os.path.join(HK, "hunter_saved.mcfunction"), "w", encoding="utf-8").write(
        "# generated by tools/build/r1_spiders.py (spiders_dp.py, T-032): the hook of the quest «Внук звонаря» (T-031): Toivo saved in the\n"
        "# Spider Thicket (the first talk of any player with him): q 0 (not taken) or 1 (taken) -> 2; the ringer rewards (spiders/ringer_talk, q 3)\n"
        "execute if data storage last_ember:heather {q:0} run data modify storage last_ember:heather q set value 2\n"
        "execute if data storage last_ember:heather {q:1} run data modify storage last_ember:heather q set value 2\n")
    # ---- the fire ban of the place for the staffs (tools/gen_seer.py reads zones/nofire.txt)
    p = os.path.join(ROOT, "zones/nofire.txt")
    lines = [l for l in open(p, encoding="utf-8")] if os.path.exists(p) else ["# places where the staffs light no fire (tools/gen_seer.py: seer/gen/zone_fire), not indestructible zones (T-004)\n"]
    lines = [l for l in lines if not l.startswith("spiders ")]
    lines.append("spiders         overworld box %d %d %d %d %d %d   # T-032: the Spider Thicket (the canopy would burn)\n" % (px1, zlo, pz1, px2, zhi, pz2))
    open(p, "w", encoding="utf-8").writelines(lines)
